#include <vector>
#include <omp.h>

double average(std::vector<double> const& x) {
    const std::size_t n = x.size();
    if (n == 0) return 0.0;

    double sum = 0.0;

    #pragma omp parallel for reduction(+:sum)
    for (std::size_t i = 0; i < n; ++i) {
        sum += x[i];
    }

    return sum / static_cast<double>(n);
}
